   for(boolean reverse:new boolean[]{false,true}){var held=reverse?target:caster;var missing=reverse?caster:target;held.nativePlayerActionLock().lock();try{int before=calls.get();NativeSourceOuterPair.run(caster,target,()->{if(held.nativePlayerActionLock().getHoldCount()<1||missing.nativePlayerActionLock().getHoldCount()<1)throw new AssertionError("preacquired pair exact counts");calls.incrementAndGet();});check(calls.get()==before+1&&held.nativePlayerActionLock().getHoldCount()==1&&!missing.nativePlayerActionLock().isLocked()&&local.get()==null,"one-held pair releases only its acquired peer");var boom=new IllegalStateException("detached-body");boolean exact=false;try{NativeSourceOuterPair.run(caster,target,()->{throw boom;});}catch(IllegalStateException e){exact=e==boom;}check(exact&&held.nativePlayerActionLock().getHoldCount()==1&&!missing.nativePlayerActionLock().isLocked()&&local.get()==null,"original body exception propagates, scope and peer released");}finally{held.nativePlayerActionLock().unlock();NativePlayerActionScope.unlocked(held);}}
